using System.Globalization;
using System.Text.Json;
using Microsoft.Data.Sqlite;
using PFA_FVG_Scanner.Domain.Forward;

namespace PFA_FVG_Scanner.Data;

public sealed record ForwardIncident(string IncidentId,string CampaignId,string Category,DateTime OccurredAtUtc,string Summary,string EvidenceJson,string ContentHash);
public sealed record ForwardCampaignDashboard(ForwardCampaign Campaign,IReadOnlyList<ForwardDailySnapshot> Snapshots,IReadOnlyList<ForwardComparison> Comparisons,IReadOnlyList<ForwardIncident> Incidents);

public sealed class ForwardCampaignRepository
{
    private readonly PfaDatabase _database;public ForwardCampaignRepository(PfaDatabase database)=>_database=database;
    public async Task CreateAsync(ForwardCampaign campaign,CancellationToken token=default)
    {if(campaign.CanPromoteStrategy)throw new UnauthorizedAccessException("Forward campaigns cannot promote strategies.");campaign.Expectation.Validate();var json=JsonSerializer.Serialize(campaign);await using var connection=_database.CreateConnection();await connection.OpenAsync(token);await using var transaction=(SqliteTransaction)await connection.BeginTransactionAsync(token);await using(var check=connection.CreateCommand()){check.Transaction=transaction;check.CommandText="SELECT CampaignJson FROM ForwardCampaigns WHERE CampaignId=$id";Add(check,"$id",campaign.CampaignId);var scalar=await check.ExecuteScalarAsync(token);if(scalar is not null&&Convert.ToString(scalar,CultureInfo.InvariantCulture)!=json)throw new InvalidOperationException("Forward campaign definitions are immutable.");if(scalar is not null){await transaction.RollbackAsync(token);return;}}
        await using(var command=connection.CreateCommand()){command.Transaction=transaction;command.CommandText="INSERT INTO ForwardCampaigns(CampaignId,AccountId,InstanceId,StrategyId,StrategyVersion,ExpectationId,ExpectationContentHash,CampaignJson,CreatedAtUtc,CanPromoteStrategy) VALUES($id,$account,$instance,$strategy,$version,$expectation,$hash,$json,$created,0)";Add(command,"$id",campaign.CampaignId);Add(command,"$account",campaign.AccountId);Add(command,"$instance",campaign.InstanceId);Add(command,"$strategy",campaign.StrategyId);Add(command,"$version",campaign.StrategyVersion);Add(command,"$expectation",campaign.Expectation.ExpectationId);Add(command,"$hash",campaign.Expectation.ContentHash());Add(command,"$json",json);Add(command,"$created",campaign.CreatedAtUtc.ToString("O"));await command.ExecuteNonQueryAsync(token);}
        await InsertEventAsync(connection,transaction,Event(campaign,"Created",ForwardCampaignStatus.Created,campaign.CreatedAtUtc,campaign.CreatedBy,"campaign-created"),token);await transaction.CommitAsync(token);}
    public async Task AppendEventAsync(ForwardCampaignEvent value,CancellationToken token=default){await using var connection=_database.CreateConnection();await connection.OpenAsync(token);await InsertEventAsync(connection,null,value,token);}
    public async Task SaveHealthAsync(ForwardHealthSample value,CancellationToken token=default)=>await InsertImmutableAsync("ForwardHealthSamples","SampleId",value.SampleId,value.ContentHash,JsonSerializer.Serialize(value),"INSERT INTO ForwardHealthSamples(SampleId,CampaignId,SampledAtUtc,FeedHealthy,FeedStale,ContentHash,SampleJson) VALUES($id,$campaign,$time,$healthy,$stale,$hash,$json)",[("$campaign",value.CampaignId),("$time",value.SampledAtUtc.ToString("O")),("$healthy",value.FeedHealthy?1:0),("$stale",value.FeedStale?1:0)],token);
    public async Task SaveSnapshotAsync(ForwardDailySnapshot value,CancellationToken token=default){if(value.CanPromoteStrategy)throw new UnauthorizedAccessException("Forward snapshots cannot promote strategies.");await InsertImmutableAsync("ForwardDailySnapshots","SnapshotId",value.SnapshotId,value.ContentHash,JsonSerializer.Serialize(value),"INSERT INTO ForwardDailySnapshots(SnapshotId,CampaignId,TradingDate,KnownAtUtc,ContentHash,SnapshotJson,CanPromoteStrategy) VALUES($id,$campaign,$date,$known,$hash,$json,0)",[("$campaign",value.CampaignId),("$date",value.TradingDate.ToString("yyyy-MM-dd")),("$known",value.KnownAtUtc.ToString("O"))],token);}
    public async Task SaveComparisonAsync(ForwardComparison value,CancellationToken token=default){if(value.CanPromoteStrategy)throw new UnauthorizedAccessException("Forward comparisons cannot promote strategies.");await InsertImmutableAsync("ForwardComparisons","ComparisonId",value.ComparisonId,value.ContentHash,JsonSerializer.Serialize(value),"INSERT INTO ForwardComparisons(ComparisonId,CampaignId,Status,ComparedAtUtc,ContentHash,ComparisonJson,CanPromoteStrategy) VALUES($id,$campaign,$status,$time,$hash,$json,0)",[("$campaign",value.CampaignId),("$status",value.Status.ToString()),("$time",value.ComparedAtUtc.ToString("O"))],token);}
    public async Task SaveIncidentAsync(ForwardIncident value,CancellationToken token=default)=>await InsertImmutableAsync("ForwardIncidents","IncidentId",value.IncidentId,value.ContentHash,value.EvidenceJson,"INSERT INTO ForwardIncidents(IncidentId,CampaignId,Category,OccurredAtUtc,Summary,EvidenceJson,ContentHash) VALUES($id,$campaign,$category,$time,$summary,$json,$hash)",[("$campaign",value.CampaignId),("$category",value.Category),("$time",value.OccurredAtUtc.ToString("O")),("$summary",value.Summary)],token);
    public async Task<ForwardCampaign?> FindAsync(string campaignId,CancellationToken token=default){await using var connection=_database.CreateConnection();await connection.OpenAsync(token);return await ReadCampaignAsync(connection,campaignId,token);}
    public async Task<IReadOnlyList<ForwardCampaign>> GetByStatusAsync(ForwardCampaignStatus status,CancellationToken token=default){var ids=new List<string>();await using var connection=_database.CreateConnection();await connection.OpenAsync(token);await using(var command=connection.CreateCommand()){command.CommandText="SELECT CampaignId FROM ForwardCampaigns ORDER BY CreatedAtUtc";await using var reader=await command.ExecuteReaderAsync(token);while(await reader.ReadAsync(token))ids.Add(reader.GetString(0));}var values=new List<ForwardCampaign>();foreach(var id in ids){var value=await ReadCampaignAsync(connection,id,token);if(value?.Status==status)values.Add(value);}return values;}
    public async Task<IReadOnlyList<ForwardHealthSample>> GetHealthAsync(string campaignId,DateTime startUtc,DateTime endUtc,CancellationToken token=default)=>await ReadJsonAsync<ForwardHealthSample>("SELECT SampleJson FROM ForwardHealthSamples WHERE CampaignId=$campaign AND SampledAtUtc>=$start AND SampledAtUtc<$end ORDER BY SampledAtUtc",campaignId,startUtc,endUtc,token);
    public async Task<IReadOnlyList<ForwardDailySnapshot>> GetSnapshotsAsync(string campaignId,CancellationToken token=default)=>await ReadJsonAsync<ForwardDailySnapshot>("SELECT SnapshotJson FROM ForwardDailySnapshots WHERE CampaignId=$campaign ORDER BY TradingDate",campaignId,null,null,token);
    public async Task<ForwardCampaignDashboard?> DashboardAsync(string campaignId,CancellationToken token=default){var campaign=await FindAsync(campaignId,token);if(campaign is null)return null;var snapshots=await GetSnapshotsAsync(campaignId,token);var comparisons=await ReadJsonAsync<ForwardComparison>("SELECT ComparisonJson FROM ForwardComparisons WHERE CampaignId=$campaign ORDER BY ComparedAtUtc",campaignId,null,null,token);var incidents=await ReadIncidentsAsync(campaignId,token);return new(campaign,snapshots,comparisons,incidents);}
    public static ForwardCampaignEvent Event(ForwardCampaign campaign,string type,ForwardCampaignStatus status,DateTime at,string actor,string reason){var hash=ForwardHash.Of(JsonSerializer.Serialize(new{campaign.CampaignId,type,status,at,actor,reason}));return new($"FWE-{hash[..32]}",campaign.CampaignId,type,status,at,actor,reason,hash);}
    private static async Task<ForwardCampaign?> ReadCampaignAsync(SqliteConnection connection,string id,CancellationToken token){await using var command=connection.CreateCommand();command.CommandText="SELECT CampaignJson FROM ForwardCampaigns WHERE CampaignId=$id";Add(command,"$id",id);var scalar=await command.ExecuteScalarAsync(token);if(scalar is null)return null;var campaign=JsonSerializer.Deserialize<ForwardCampaign>(Convert.ToString(scalar,CultureInfo.InvariantCulture)!)!;await using var latest=connection.CreateCommand();latest.CommandText="""
        SELECT Status,OccurredAtUtc,Reason,
          (SELECT MIN(OccurredAtUtc) FROM ForwardCampaignEvents s WHERE s.CampaignId=$id AND s.Status='Running'),
          (SELECT MAX(OccurredAtUtc) FROM ForwardCampaignEvents t WHERE t.CampaignId=$id AND t.Status IN ('Stopped','Completed'))
        FROM ForwardCampaignEvents WHERE CampaignId=$id ORDER BY OccurredAtUtc DESC,rowid DESC LIMIT 1
        """;Add(latest,"$id",id);await using var reader=await latest.ExecuteReaderAsync(token);if(!await reader.ReadAsync(token))return campaign;var status=Enum.Parse<ForwardCampaignStatus>(reader.GetString(0));DateTime? started=reader.IsDBNull(3)?null:DateTime.Parse(reader.GetString(3),CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind);DateTime? stopped=reader.IsDBNull(4)?null:DateTime.Parse(reader.GetString(4),CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind);return campaign with{Status=status,StartedAtUtc=started,StoppedAtUtc=stopped,StatusReason=reader.GetString(2)};}
    private async Task InsertImmutableAsync(string table,string idColumn,string id,string hash,string json,string sql,IReadOnlyList<(string Name,object? Value)> values,CancellationToken token){await using var connection=_database.CreateConnection();await connection.OpenAsync(token);await using(var check=connection.CreateCommand()){check.CommandText=$"SELECT ContentHash FROM {table} WHERE {idColumn}=$id";Add(check,"$id",id);var scalar=await check.ExecuteScalarAsync(token);if(scalar is not null&&Convert.ToString(scalar,CultureInfo.InvariantCulture)!=hash)throw new InvalidOperationException($"{table} records are immutable.");if(scalar is not null)return;}await using var command=connection.CreateCommand();command.CommandText=sql;Add(command,"$id",id);Add(command,"$hash",hash);Add(command,"$json",json);foreach(var value in values)Add(command,value.Name,value.Value);await command.ExecuteNonQueryAsync(token);}
    private static async Task InsertEventAsync(SqliteConnection connection,SqliteTransaction? transaction,ForwardCampaignEvent value,CancellationToken token){await using var command=connection.CreateCommand();command.Transaction=transaction;command.CommandText="INSERT OR IGNORE INTO ForwardCampaignEvents(CampaignEventId,CampaignId,EventType,Status,OccurredAtUtc,Actor,Reason,ContentHash) VALUES($id,$campaign,$type,$status,$time,$actor,$reason,$hash)";Add(command,"$id",value.CampaignEventId);Add(command,"$campaign",value.CampaignId);Add(command,"$type",value.EventType);Add(command,"$status",value.Status.ToString());Add(command,"$time",value.OccurredAtUtc.ToString("O"));Add(command,"$actor",value.Actor);Add(command,"$reason",value.Reason);Add(command,"$hash",value.ContentHash);await command.ExecuteNonQueryAsync(token);}
    private async Task<IReadOnlyList<T>> ReadJsonAsync<T>(string sql,string campaign,DateTime? start,DateTime? end,CancellationToken token){var list=new List<T>();await using var connection=_database.CreateConnection();await connection.OpenAsync(token);await using var command=connection.CreateCommand();command.CommandText=sql;Add(command,"$campaign",campaign);if(start.HasValue)Add(command,"$start",start.Value.ToString("O"));if(end.HasValue)Add(command,"$end",end.Value.ToString("O"));await using var reader=await command.ExecuteReaderAsync(token);while(await reader.ReadAsync(token))list.Add(JsonSerializer.Deserialize<T>(reader.GetString(0))!);return list;}
    private async Task<IReadOnlyList<ForwardIncident>> ReadIncidentsAsync(string campaign,CancellationToken token){var list=new List<ForwardIncident>();await using var connection=_database.CreateConnection();await connection.OpenAsync(token);await using var command=connection.CreateCommand();command.CommandText="SELECT IncidentId,CampaignId,Category,OccurredAtUtc,Summary,EvidenceJson,ContentHash FROM ForwardIncidents WHERE CampaignId=$campaign ORDER BY OccurredAtUtc";Add(command,"$campaign",campaign);await using var reader=await command.ExecuteReaderAsync(token);while(await reader.ReadAsync(token))list.Add(new(reader.GetString(0),reader.GetString(1),reader.GetString(2),DateTime.Parse(reader.GetString(3),CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind),reader.GetString(4),reader.GetString(5),reader.GetString(6)));return list;}
    private static void Add(SqliteCommand command,string name,object? value)=>command.Parameters.AddWithValue(name,value??DBNull.Value);
}
